 const leg=(z,i)=>`<div class="plg" data-open="${z.g.k}"><span class="n">${i+1}</span><div class="c"><b>${z.o.l}</b><small>${z.g.h} vs ${z.g.a}${z.g.t?" · "+z.g.t:""}</small></div><div class="r"><b>${pc(z.o.p)}</b><small>${z.real?"":"≈ "}${z.d.toFixed(2)}</small></div></div>`;
