let SIMR=null,SIMT=[];
function simStop(){if(SIMR)cancelAnimationFrame(SIMR);SIMR=null;SIMT.forEach(clearTimeout);SIMT=[]}
function simStart(g){simStop();const cv=document.getElementById("dcv");if(!cv)return;const cx=cv.getContext("2d"),img=new Image(),off=document.createElement("canvas"),oc=off.getContext("2d");
 const t0=performance.now(),REV=2600;let ready=false;img.onload=()=>{ready=true};img.src=RIMG;
 const wr=document.getElementById("dwr"),pc=document.getElementById("dpc"),px=document.getElementById("dpx"),NS="http://www.w3.org/2000/svg";
 /* lineas de "escritura" en la pagina derecha */
 const LN=[[100,9],[100,16],[100,23],[100,30],[100,37]];let li=0,lt=0,cur=null;
 function newLine(){if(li>=LN.length){li=0;wr.innerHTML=""}const [x,y]=LN[li],len=48+Math.random()*16;let d=`M${x} ${y}`;for(let k=0;k<len/6;k++)d+=` q3 ${k%2?3:-3} 6 0`;cur={el:document.createElementNS(NS,"path"),x,y,len};cur.el.setAttribute("d",d);const L=cur.len*1.15;cur.el.setAttribute("stroke-dasharray",L);cur.el.setAttribute("stroke-dashoffset",L);cur.L=L;wr.appendChild(cur.el);lt=performance.now();li++}
 newLine();
 function frame(now){const t=now-t0;
  if(ready){const p=Math.min(1,t/REV),e=1-Math.pow(1-p,2.2),b=Math.max(1,Math.round(26*(1-e)));const w=Math.max(1,Math.ceil(220/b)),h=Math.max(1,Math.ceil(340/b));
   off.width=w;off.height=h;oc.imageSmoothingEnabled=true;oc.drawImage(img,0,0,w,h);cx.imageSmoothingEnabled=b<=1;cx.fillStyle="#fff";cx.fillRect(0,0,220,340);cx.drawImage(off,0,0,w,h,0,0,220,340);
   cx.globalAlpha=1;if(p<1){/* destellos de pixel cargando */cx.fillStyle="rgba(31,107,255,.35)";for(let k=0;k<14;k++){const s=b*1.0;cx.fillRect(Math.floor(Math.random()*220/s)*s,Math.floor(Math.random()*210/s)*s,s,s)}}
   px.style.opacity=p<1?1:0}
  /* lapiz escribiendo */
  const k=Math.min(1,(now-lt)/900);cur.el.setAttribute("stroke-dashoffset",cur.L*(1-k));
  const tx=cur.x+cur.len*k,ty=cur.y+Math.sin(k*cur.len/3)*1.6;pc.setAttribute("transform",`translate(${tx.toFixed(1)} ${ty.toFixed(1)})`);
  if(k>=1&&now-lt>1100)newLine();
  SIMR=requestAnimationFrame(frame)}
 SIMR=requestAnimationFrame(frame)}

function openGame(k){OPEN=k;const g=getG(k);TMR.forEach(clearTimeout);TMR=[];$("ov").classList.remove("hide");$("ov").scrollTop=0;document.body.style.overflow="hidden";
 $("stage").classList.remove("hide");$("res").classList.add("hide");$("stage").innerHTML=stageHTML(g);simStart(g);
 const L=lines(g);L.forEach((t,i)=>TMR.push(setTimeout(()=>{const d=document.createElement("div");d.className="ll"+(i==L.length-1?" ok":"");d.textContent=(i==L.length-1?"✔ ":"▸ ")+t;$("log").appendChild(d);$("pg").style.width=((i+1)/L.length*100)+"%"},i*420+250)));
 TMR.push(setTimeout(()=>showRes(1),L.length*420+800))}
function showRes(fr){simStop();TMR.forEach(clearTimeout);TMR=[];if(!OPEN)return;$("stage").classList.add("hide");const r=$("res");r.classList.remove("hide","anim");r.innerHTML=card(getG(OPEN));if(fr===1)AVX.anim(r)}
function closeGame(){simStop();TMR.forEach(clearTimeout);TMR=[];OPEN=null;$("ov").classList.add("hide");document.body.style.overflow=""}
let buf="";const CODE="7779",dots=[...document.querySelectorAll("#dots i")],msg=$("msg"),pad=$("pad");
["1","2","3","4","5","6","7","8","9","","0","⌫"].forEach(k=>{const b=document.createElement("button");b.textContent=k;if(!k)b.style.visibility="hidden";b.onclick=()=>key(k);pad.appendChild(b)});
function key(k){if(k==="⌫")buf=buf.slice(0,-1);else if(/\d/.test(k)&&buf.length<4)buf+=k;dots.forEach((d,i)=>d.classList.toggle("on",i<buf.length));
 if(buf.length===4){if(buf===CODE){msg.textContent="ACCESO CONCEDIDO";setTimeout(()=>{$("lock").classList.add("hide");$("app").classList.remove("hide");draw()},500)}
 else{msg.textContent="CÓDIGO INCORRECTO";const l=$("lock");l.classList.add("shake");setTimeout(()=>{l.classList.remove("shake");buf="";dots.forEach(d=>d.classList.remove("on"));msg.textContent="INGRESA CÓDIGO DE ACCESO"},500)}}}
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&OPEN)closeGame();if($("lock").classList.contains("hide"))return;if(e.key==="Backspace")key("⌫");else if(/^\d$/.test(e.key))key(e.key)});

AVX.on(()=>{const y=window.scrollY,os=$("ov").scrollTop;try{draw()}catch(e){}window.scrollTo(0,y);if(OPEN&&!$("res").classList.contains("hide")){showRes();$("ov").scrollTop=os}});
